package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSoDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Maqalka Diigga ama Dameerka", "Allahayow waxaan ku waydiisanayaa fadligaaga ( diiqii). - Allaah ayaan ka magan galay shaydaanka la nacnaday (dameerka).", "Diiqu markuu maqlo fadliga Alle waydii; marka aad maqasho dameer ciyaan ah ka magangal shaydaan.", "Diiqu wuxuu arkay malag, dameerkuna wuxuu arkay shaydaan."),
        "dua_something_liked" to DuaText("Inaad aragto wax la yaab leh ( Against Evil Eye)", "Wixii Alle ka yeelay. Allow barakee.", "Markaad aragto shay la yaab leh oo uu leeyahay, u ducee duco.", "Ducada ducada waxay ka hortagtaa isha xun."),
        "dua_sell_buy_debt_repaid" to DuaText("Marka Dib u Bixinta Dayn", "Alle haku barakeeyo qoyskaaga iyo maalkaaga.", "Deyn-bixiyuhu markuu deyn bixinayo.", "Soo celinta deyntu waa mahadnaq iyo dib u bixin."),
        "dua_talbiyah" to DuaText("Talbiyah", "Waa i kan Alloow waa i kan. Waa i kan, Adigu lammaane ma lihid, waa i kan. Hubaal ammaanta, barakada iyo xukunka oo dhan adigaa iska leh. Ma lihid lamaane.", "qeylo dheer kadib soo galitaanka ixraamka.", "Astaanta Xajka iyo Cumrada."),
        "dua_yamani_hajar" to DuaText("Inta u dhaxaysa Rukn Yamani iyo Xajar Aswad", "Eebow na sii adduunyo wanaag, aakhirona wanaag, naga ilaali cadaabka naarta.", "Tawaaf, oo u dhaxaysa Geeska Yemen iyo Dhagaxa Madow.", "Nabiga ﷺ ayaa meeshan ka akhriyey isagoo tawaaf ah."),
        "dua_safa_marwa" to DuaText("On Safa iyo Marwah", "Ma jiro cid xaq u leh in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin. Xukunka isagaa iska leh mahadna isagaa iska leh, wax walbana wuu karaa. Ma jiro cid xaq u leh in la caabudo Alle mooyee, Isaga oo keliya; Wuu oofiyay ballankii, wuuna u gargaaray addoonkiisii, kaligiina wuu jabiyay ururadii.", "Safa oo la fuulo oo Qiblada loo jeediyo (saddex jeer).", "Siidii nabiga ﷺ ee Safa iyo Marwah."),
        "dua_arafah" to DuaText("Ducada ugu Wanaagsan Maalinta Carafo", "Ma jiro cid xaq u leh in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin. Xukunka isagaa iska leh mahadna isagaa iska leh, wax walbana wuu karaa.", "Maalinta Carafa - ducada ugu fiican.", "Ducada ugu khayrka badan waa ducada maalinta Carafo, hadalka ugu wanagsanna waa kuwan."),
        "dua_takbeer_tashreeq" to DuaText("Takbiir-e-Tashriiq", "Allaahu akbar, Allaahu akbar. Allaah mooyee ilaah kale ma jiro. Allaah baa weyn, Allaah baa weyn, mahad oo dhan Allaah ayaa iska leh.", "Kadib salaad kasta oo waajib ah laga bilaabo Fajarka 9-ka Dul-Xijja ilaa Casar 13-ka Dul-Xijjah.", "Waxaa wariyey Cali iyo Ibnu Mascuud (RA) — waajib sida ay qabaan Xanafiyada."),
        "dua_zamzam" to DuaText("Cabitaanka Zamzam", "Allahayow waxaan ku waydiisanayaa cilmi anfaca, arzuqo badan iyo cudur kasta daawo.", "Markaad cabto Zamzam, u duceyso wax kasta oo aad damacsan tahay.", "Zamzam waxa loogu talagalay wax kasta oo lagu sakhraamo (Ibnu Maajah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Ka Milicsiga Abuurka", "Eebow waxaas oo dhan micne darro kuma aadan abuurin. Adaa nasahane ee naga dhawr cadaabka naarta.", "Ducada kuwa ka fiirsada abuurista samooyinka iyo dhulka.", "Ducada dadka wax garadka ah (ulul-albaab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Waxaan Maqalnay U Yeedhay Iimaanka", "Eebow waxaan maqallay u yeedha oo ku dhawaaqaya iimaanka oo leh rumeeya Eebihiin, waana rumaynay. Eebow noo dhaaf danbiganaga, naga saar xumaantayada, nagana dil kuwa dhawrsada.", "Ducada iimaanka iyo dhimashada kuwa xaqa ah dhexdooda.", "Duco cafis iyo dhaman wanaagsan."),
        "dua_q_atina_ma_waadtana" to DuaText("Noogu Balan Qaaday", "Eebow na sii waxaad noogu yaboohday Rasuuladaada hana na dullayn maalinta qiyaame. Illeen Adiga Ballankaaga ma jabinayso.", "In laga cararo dulliga maalinta qiyaame.", "Aakhiro sharaf raadis."),
        "dua_q_israfana" to DuaText("Dhaaf naga dhaaf", "Eebow noo dhaaf dambiganada iyo xad gudubkanaga, noogana yeel lugahaaga noogana gargaar qoomka gaalada ah.", "Ducadii saxaabiyadii hore.", "Duco samir iyo cafis."),
        "dua_q_jamiun_nas" to DuaText("Waxaad soo ururin doontaa bani-aadmiga", "Eebow waxaad kulmin dadka maalin aan shaki lahayn. Eebbana ma baajiyo ballankiisa.", "Iyagoo sugan maalinta qiyaame.", "Ducada kuwa ku adag aqoonta."),
        "dua_q_maash_shahidin" to DuaText("Nagu qor Markhaatiyaasha dhexdooda", "Eebow waan rumaynay ee nagu qor marag-kac.", "Ducadii kuwii xaqa gartay oo rumeeyey.", "Duco loogu talagalay aqbalaadda iimaanka qofka."),
        "dua_q_la_tajalna_zalimin" to DuaText("Ma La Socon Daalimiinta", "Eebow ha na yeelin qoom daalimiinta ah.", "Ducada reer al-Acraaf.", "In laga cararo aayaha daalimiinta."),
        "dua_q_tawaffana_muslimin" to DuaText("Samir iyo Geeriba hadaan nahay Muslim", "Eebow samir ha noogu shubo oo naga dil inagoo muslim ah.", "Ducadii Saaxiriintii Fircoon markay Rumeeyeen.", "Samir ku jira imtixaan iyo dhammaadka iimaanka."),
        "dua_q_la_tajalna_fitnah" to DuaText("Maaha Maxkamad Dulmi", "Allaah uunbaan talo saaranay. Eebow ha nooga dhigin fitno qoom daalimiinta ah, nagana dhawr naxariistaada qoom gaalada ah.", "Ducadii reer Muuse (AS).", "Duco ka samata bixinta dulmiga iyo daalimiinta."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Ducadii Nuux (AS) danbi dhaaf", "Eebow waxaan kaa magan galay inaan ku warsado waxaanan cilmi u lahayn. Haddaadan ii dambi dhaafin oodan ii naxariisan waxaan ka mid noqon kuwa khasaaray.", "Ducadii tawbada ee Nabi Nuux (AS).", "Cashar ku saabsan weydiinta asluubta habboon."),
        "dua_q_mudkhala_sidq" to DuaText("Gelitaanka iyo ka bixida Runta", "Eebow i gali si xaq ah oo ku baxo xaqa, igana yeel agtaada xujo gargaari.", "Kahor intaadan gelin hawl cusub, guri ama meel.", "Ducadu wuxuu baray nabiga ﷺ waagii hijriga."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua of Zakariya (AS) - Keligay ha iga Tagin", "Eebow ha iga tagin, adaa wax dhaxli kara.", "Kuwa carruurta doonaya.", "Ducadan Alle waxa uu ku siiyay Yaxye (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Goob Barakaysan Oo Soo Degto", "Eebbow i daa aan ku soo deggo meel barakeysan, adaa ugu kheyr badan kuwa dhulka keena.", "Markaad u guurto guri cusub ama aad meel joogsato - ducada Nuux (AS).", "Duco loogu duceeyo meel cusub."),
        "dua_q_amanna_faghfir" to DuaText("Waanu Rumaysanay ee noo Cafi", "Eebow waan rumaynay ee noo dambi dhaaf oo noo naxariiso adigana waxaad tahay Naxariista roon.", "Ducada adoomada Allah ee suuban.", "Duco dhamaystiran oo cafis iyo naxariis ah."),
        "dua_q_isrif_jahannam" to DuaText("Cadaabka Jahannamo la iska ilaaliyo", "Eebow naga leexi cadaabka Jahannamo. 021-046 (Nabigu) waa cadaab ku hadha. Illeen waa deegaan iyo deegaan xun.", "Ducada addoomada Eebaha Raxmaanka ah (Cibad ar-Raxmaan).", "Duco Qur'aanka Kariimka Naarta."),
        "dua_q_hab_li_hukman" to DuaText("Ducadii Ibraahim (AS) - Xikmad iyo Janno", "Eebow i sii murtida oo igu darraafi kuwa dhawrsada, Igana yeel xuska sharafta leh ee qarniyada danbe, igana yeel kuwa dhaxli jannatul firdowsa.", "Weydiiso xikmad, kooxda kuwa xaqa ah iyo Jannada.", "Ducada Ibrahim oo dhamaystiran (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua of Luud (AS) - Badbaadi qoyskayga", "Eebow iga kori aniga iyo qoyskaygaba waxay falayaan.", "In qoyska laga ilaaliyo deegaanka xumaanta.", "In qoyska laga ilaaliyo xumaanta."),
        "dua_q_sulaiman_awzini" to DuaText("Dua of Sulaiman (AS) Mahadcelin", "Eebow ii yeel inaan ku shukriyo Nicmadaada aad igu Nicmaysay aniga iyo Waalidkayba, iyo inaan Sameeyo Camal Fiican oo aad raalli ka tahay, Ina geli Naxariistaada Adoomadaada Suubban.", "Awood u leh in lagu shukriyo barakooyinka.", "Ducadii mahadnaqa Sulaymaan (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Ducadii Muuse (AS) - Waan Qalday Naftayda", "Eebow anigaa naftayda dulmiyay ee ii dambi dhaaf.", "Toobad degdeg ah ka dib qalad.", "Allaha u danbi dhaafey Muuse (AS)."),
        "dua_q_musa_najjini" to DuaText("Ducadii Muuse (AS) - Iga badbaadi daalimiinta", "Eebow iga badbaadi dadka daalimiinta ah.", "Marka laga cabsado daalimiinta.", "Ducadii Muuse (AS) markii uu Masar ka baxayay."),
        "dua_q_lut_unsurni" to DuaText("Dua of Luud (AS) - Caawinta Ka-hortagga Musuq-maasuqa", "Eebow iga Gargaar Qoomka Faasiqiinta ah.", "Si loo caawiyo kuwa faafinaya musuqmaasuqa.", "Ducada kuwa xaqa ku taagan."),
        "dua_q_hab_li_salihin" to DuaText("Ducadii Ibraahim (AS) ee Ubadka Xaqa ah", "Eebow iga yeel (ubad) kuwa suuban.", "Weydiinta carruurta xaqa ah.", "Ducadan Ismaaciil (AS) ayaa la siiyay."),
        "dua_q_wasita_kulla_shay" to DuaText("Ducada Malaa'igta Carshiga Xambaarsan", "Eebow adaa koobay wax walba naxariis iyo cilmi, ee u dambi dhaaf kuwa toobad keena oo raaca jidkaaga, kana dhawr cadaabka naarta.", "Malaa'igta xanbaarsan Carshiga ayaa ducadan u yeelaya Mu'miniinta.", "Waa la akhriyay iyadoo ujeedadu tahay in lagu daro ducada malaa'igta."),
        "dua_q_ikhwanina" to DuaText("Walaalaheennii naga horeeyay", "Eebow noo dambi dhaaf annaga iyo walaalaheen kuwii nooga horreeyey iimaanka, hana ka xumaanin quluubtayada kuwa xaqa rumeeyey. Eebow adaa naxariis badane.", "Duco ku socota Mu'miniinta ka hor iyo qalbi nadiif ah.", "Duco ku socota saxaabada sharafta leh (RA) iyo mu'miniintii hore."),
        "dua_q_alayka_tawakkalna" to DuaText("Adiga ayaan ku Tiirsanahay (Ibraahim CS)", "Eebow adaa talo saaranaynaa, xaggaagaana u noqonaynaa. Eebow ha nooga dhigin fitno gaalada ee noo dambi dhaaf. Eebow adaa adkaade falsane.", "Ducadii Ibraahim (AS) iyo asxaabtiisa.", "Waa duco ah talo saarashada Alle iyo u noqoshadiisa."),
        "dua_q_atmim_nurana" to DuaText("Iftiinkeena qumman", "Eebow noo taam-yeel nuur-naga noo dambi dhaaf. illeen adaa wax walba kara.", "Ducada Mu'miniinta Maalinta Qiyaame.", "Weydiinta iftiinka Siraad."),
        "dua_q_asiya_baytan" to DuaText("Dua of Asia - Guri ku yaal Jannah", "Eebow iiga dhis agtaada guri Jannada ah, iga kori Fircoon iyo camalkiisa, igana nabad geli qoomka daalimiinta ah.", "Ducada Aasiya, xaaskii Fircoon.", "Eebe wuxuu uga yeelay tusaale Mu'miniinta."),
        "dua_adhan_response" to DuaText("Isagoo ka jawaabaya Adhan", "Xoog iyo awood ma jiro Allaah mooyee.", "Ku celi waxa uu mu'adinku leeyahay; at 'Hayya 'alas-saalah' iyo 'Hayya 'alal-falah' sidan dheh.", "Ruuxii qalbigiisa ka soo jawaaba wuxuu gelayaa Jannada."),
        "dua_adhan_shahadah" to DuaText("Kadib Shahaadada Muazin", "Waxa kale oo aan ka marag kacayaa in aan cidina xaq u lahayn in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin, Muxammadna ﷺ waa addoonkiisii ​​iyo rasuulkiisii. Waxaan ku raalli ahay Allaah inuu Rabbi ii yahay, Muxammad ﷺ Rasuul Ahaan, Islaamkana Diin ahaan.", "Markuu maqlay markhaatifurka mu'adinka ee iimaanka.", "Dembigiisa waa cafiyan yihiin."),
        "dua_istiftah_baid" to DuaText("Ducada furitaanka: iga fogee dembiyada", "Allahayow dambigayga iga fogee sidaad bari uga fogaysay galbeedka. Allahayow dambiyada iga nadiifi sida marada cad wasakhda looga nadiifiyo. Allahayow dambigayga ku maydh biyo, baraf iyo roobdhagaxyaale.", "Takbiirta furitaanka ka dib (waxaa sidoo kale laga yaabaa in lagu yiraahdo meel Sanca ah).", "Nabigu ﷺ wuxuu akhriyay inta u dhaxaysa takbiirta iyo akhrinta."),
        "dua_hamdan_kathiran" to DuaText("Amaan Badan Rukuu Ka Dib", "Rabbiyow, mahad adaa iska leh, Mahad badan oo daahir ah oo barakeysan.", "Ka dib markii ay ka soo kaceen ruku, oo ay la socdaan 'Rabbana lakal-xamd'.", "In ka badan soddon malaa'igood ayaa ku tartamayay inay noqdaan kuwii ugu horreeyay ee duuba."),
    )
}
